import {createWorkflows} from './workflows.js';
import {SerialTransport,BleTransport,WsTransport} from './vendor/transport.js';
import {Elm327} from './vendor/elm327.js';
import {parseDdt} from './vendor/ddt.js';
import {listZip,extractText} from './vendor/unzip.js';
import {PIDS,CommandChannel,decodeDtcs,decodeVin} from './obd.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['dashboard','◉','Přístrojová deska'],['live','⌁','Živá data'],['faults','△','Chybové kódy'],['ecus','▦','Řídicí jednotky'],['expert','◇','Expert · DDT'],['service','⚒','Servisní funkce'],['backups','↶','Zálohy a záznamy'],['console','›_','Pro konzole'],['settings','⚙','Nastavení'],['about','ⓘ','Podpora a informace']];
const profiles={iv:{name:'Espace IV',years:'2003–2014',code:'X81',note:'CAN i K-line dle jednotky. Renault funkce vyžadují přesnou ECU definici.'},v:{name:'Espace V',years:'2015–2023',code:'XFC',note:'CAN. Dostupnost funkcí závisí na ECU, databázi a případném gateway.'},vi:{name:'Espace VI',years:'2023–2024',code:'RHN',note:'Neověřeno. Nová architektura a zabezpečená brána mohou omezit diagnostiku.'}};
let settings;try{settings=JSON.parse(localStorage.getItem('espace.settings'))||{};}catch{settings={};}settings={profile:'iv',year:2008,transport:'ble',baud:38400,bridge:'ws://127.0.0.1:8472',...settings};
let state={connected:false,demo:false,busy:false,values:{},dtcs:[],faultRead:false,vin:null,history:[],log:[],records:[],recording:false,view:'dashboard',unsupported:new Set(),ecu:null,ddtResults:[],backups:[],paused:false};
try{state.backups=JSON.parse(localStorage.getItem('espace.backups'))||[];}catch{}
let transport,channel,elm,protocol='obd',timer,ddtFiles=[],ddtIndex=[],zipData,pollGeneration=0;
const workflows=createWorkflows({$,esc,state,getSettings:()=>settings,toast,render,updateStatus,job,download,modal,getIndex:()=>ddtIndex,scanRequest:async(ecu,q,timeout)=>{if(!state.connected||state.demo)throw Error('Není skutečné spojení.');state.ecu=ecu;await ensureDdt();return elm.requestIsoTp(ecu.handle(),q,{timeout});},healthCheck:async()=>{if(state.demo)return {status:'Simulace',readiness:'MIL vypnuto, 0 emisních DTC',values:{voltage:14.2,rpm:0,coolant:85,speed:0}};await ensureObd();const values={};for(const key of ['voltage','rpm','coolant','speed'])values[key]=await channel.pid(PIDS.find(p=>p.key===key));const response=await channel.command('0101',10000);const match=response.toUpperCase().replace(/\s/g,'').match(/4101([0-9A-F]{8})/);return {status:'Pouze čtení',values,readiness:match?{mil:!!(parseInt(match[1].slice(0,2),16)&128),emissionDtcCount:parseInt(match[1].slice(0,2),16)&127,rawMonitorBytes:match[1].slice(2)}:null};}});
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',5500);}
function save(){localStorage.setItem('espace.settings',JSON.stringify(settings));profileLabel();}
function profileLabel(){const p=profiles[settings.profile];$('#vehicleName').textContent=p.name;$('#vehicleDetail').textContent=p.years+' · '+p.code;}
function fmt(key,d=0){const v=state.values[key];return v==null?'—':Number(v).toLocaleString('cs-CZ',{maximumFractionDigits:d,minimumFractionDigits:d});}
function log(dir,text){state.log.push({time:new Date().toISOString(),dir,text});if(state.log.length>1000)state.log.shift();if(state.view==='console')renderLog();}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
function exportReport(){download('espace-report-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'EspaceWeb 0.2',simulated:state.demo,profile:settings.profile,year:settings.year,vin:state.vin,timestamp:new Date().toISOString(),values:state.values,dtcs:state.dtcs,faultRead:state.faultRead,log:state.log,records:state.records},null,2));}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();}
$('#close').onclick=()=>$('#modal').close();$('#menu').onclick=()=>$('aside').classList.toggle('open');$('#export').onclick=exportReport;
$('#nav').innerHTML=nav.map(([id,icon,name])=>`<button data-view="${id}"><span class="symbol">${icon}</span>${name}${id==='faults'?'<span class="count" id="faultCount"></span>':''}</button>`).join('');
$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)location.hash=b.dataset.view;};window.onhashchange=()=>navigate();
function navigate(){const id=location.hash.slice(1)||'dashboard';state.view=nav.some(x=>x[0]===id)?id:'dashboard';$('aside').classList.remove('open');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#title').textContent=nav.find(x=>x[0]===state.view)[2];$('#subtitle').textContent=({dashboard:'Živý přehled vašeho vozidla.',live:'Standardní EOBD parametry · pouze hodnoty dostupné z ECU.',faults:'Emisní závady z motorové ECU · uložené a čekající.',ecus:'Automatický CAN sken a identifikace podle vašich DDT definic.',expert:'Čtení a řízený zápis s odpovídající DDT definicí.',service:'Dostupnost procedur se řídí konkrétní jednotkou.',backups:'Historie změn a export diagnostických dat.',console:'Surová komunikace ELM327 / diagnostika CAN.',settings:'Vozidlo, adaptér a způsob připojení.',about:'Kompatibilita, skutečný rozsah a zdrojový kód.'})[state.view];render();}
function updateStatus(){const mode=state.demo?'Demo · simulovaný Espace':state.connected?'Připojeno · '+(transport?.info||'ELM327'):'Nepřipojeno';$('#status').textContent=mode;$('#dot').classList.toggle('on',state.connected);$('#connect').textContent=state.connected?'Odpojit':'Připojit vozidlo ↗';$('#modeLabel').textContent=state.demo?'/ DEMO':'/ OBD2';$('#footstatus').textContent=state.demo?'Simulovaná data · bez vozidla':state.connected?'Spojení s adaptérem · '+(state.paused?'čtení pozastaveno':'čtení dat'):'Čtení dat · žádné spojení';$('#banner').className='banner'+(state.demo?' demo':'');$('#banner').innerHTML=state.demo?'<span>●</span><span>DEMO REŽIM · Všechny zobrazené hodnoty a závady jsou simulované.</span><button id="endDemo">Ukončit demo ×</button>':state.connected?'<span>●</span><span>Adaptér připojen. Hodnoty — nejsou dostupné nebo dosud načtené.</span><button id="pause">'+(state.paused?'Pokračovat →':'Pozastavit čtení ⏸')+'</button>':'<span>○</span><span>Vozidlo není připojeno. Prohlédněte si aplikaci bez adaptéru.</span><button id="demo">Spustit demo →</button>';$('#demo')?.addEventListener('click',startDemo);$('#endDemo')?.addEventListener('click',()=>{if(state.busy||workflows.isRunning())return toast('Nejprve zastavte probíhající postup.');disconnect();});$('#pause')?.addEventListener('click',()=>{state.paused=!state.paused;updateStatus();});$('#faultCount').textContent=state.faultRead?state.dtcs.length:'';}
function metric(label,key,unit,note='',digits=0){return `<div class="panel metric"><div class="label"><span class="glyph">⌁</span>${label}</div><div class="value" data-value="${key}" data-digits="${digits}">${fmt(key,digits)} <small>${unit}</small></div><div class="note">${note}</div></div>`;}
function dashboard(){return `<div class="dashboard"><section class="panel"><div class="panel-title">RYCHLOST A OTÁČKY <span class="pill">${state.demo?'SIMULACE':state.connected?'OBD2':'ČEKÁ NA SPOJENÍ'}</span></div><div class="hud"><div class="dial"><svg viewBox="0 0 250 250"><circle cx="125" cy="125" r="112"/><circle class="arc" cx="125" cy="125" r="112"/></svg><div class="speed" id="speed">${fmt('speed')}</div><div class="unit">KM / H</div><div class="rpm"><span id="rpm">${fmt('rpm')}</span> <small>OT/MIN</small></div></div><div class="hud-label">ESPACE / LIVE TELEMETRY</div></div></section><div class="metric-stack">${metric('CHLADICÍ KAPALINA','coolant','°C','Teplota motoru')}${metric('NAPĚTÍ ECU','voltage','V','Napájení jednotky',1)}${metric('ZATÍŽENÍ MOTORU','load','%','Vypočtené zatížení')}${metric('PALIVO','fuel','%','Hladina v nádrži')}</div></div><div class="bottom-grid"><section class="panel"><div class="panel-title">PRŮBĚH JÍZDY <span class="legend"><span><em></em>Rychlost km/h</span><span>Posledních 60 vzorků</span></span></div><div class="plot-wrap"><svg class="plot" id="chart" viewBox="0 0 600 145" preserveAspectRatio="none"></svg><div class="plot-axis"><span>−60 vzorků</span><span>Nyní</span></div></div></section><section class="panel"><div class="panel-title">STAV DIAGNOSTIKY <span>↗</span></div><div class="health-row"><span>Emisní závady</span><b class="${state.dtcs.length?'amber':'green'}">${state.faultRead?state.dtcs.length+' nalezeno':'Nenačteno'}</b></div><div class="health-row"><span>Identifikace VIN</span><b>${state.vin?esc(state.vin):'—'}</b></div><div class="health-row"><span>Přehled závad</span><button id="gotoFaults">Otevřít →</button></div></section></div>`;}
function drawChart(){const c=$('#chart');if(!c)return;const points=state.history.map((x,i)=>`${i*600/59},${130-Math.min(160,x.speed??0)*.7}`).join(' ');c.innerHTML='<defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#38b5f5" stop-opacity=".20"/><stop offset="1" stop-color="#38b5f5" stop-opacity="0"/></linearGradient></defs>'+[25,60,95,130].map(y=>`<line x1="0" y1="${y}" x2="600" y2="${y}" stroke="#243240" stroke-dasharray="3 5"/>`).join('')+(points?`<polygon points="0,145 ${points} ${(state.history.length-1)*600/59},145" fill="url(#fade)"/><polyline points="${points}" fill="none" stroke="#38b5f5" stroke-width="2"/>`:'<text x="300" y="80" fill="#53677e" text-anchor="middle" font-size="12">Čeká na živá data</text>');}
function updateValues(){document.querySelectorAll('[data-value]').forEach(el=>{const key=el.dataset.value,p=PIDS.find(p=>p.key===key);el.innerHTML=fmt(key,Number(el.dataset.digits||0))+` <small>${p?.unit||''}</small>`;});if($('#speed'))$('#speed').textContent=fmt('speed');if($('#rpm'))$('#rpm').textContent=fmt('rpm');$('.dial')?.style.setProperty('--arc',Math.max(0,Math.min(530,(state.values.speed||0)/220*530)));drawChart();$('#sampleTime').textContent=state.connected?'Aktualizace '+new Date().toLocaleTimeString('cs-CZ'):'Čeká na data';}
function live(){return `<div class="toolbar"><input id="pidSearch" placeholder="Hledat parametr…" aria-label="Hledat parametr"><button id="record" class="${state.recording?'primary':'secondary'}">${state.recording?'■ Zastavit záznam':'● Zaznamenávat'}</button><button id="csv">↓ CSV (${state.records.length})</button></div><div class="panel table-scroll"><table><thead><tr><th>PARAMETR</th><th>PID</th><th>HODNOTA</th><th>DOSTUPNOST</th></tr></thead><tbody id="pidRows">${PIDS.map(p=>`<tr data-search="${p.name.toLowerCase()}"><td><strong>${p.name}</strong></td><td class="muted">${p.id}</td><td><b data-value="${p.key}" data-digits="${['voltage','maf'].includes(p.key)?1:0}">${fmt(p.key)} <small>${p.unit}</small></b></td><td>${state.demo?'Simulace':state.unsupported.has(p.key)?'ECU neposkytuje':state.values[p.key]!=null?'Načteno':'Čeká na čtení'}</td></tr>`).join('')}</tbody></table></div>`;}
function faults(){return `<div class="toolbar"><button class="primary" id="readFaults" ${!state.connected?'disabled':''}>⟳ Načíst závady</button><button id="clearFaults" ${!state.connected||!state.faultRead?'disabled':''}>Smazat emisní závady</button><span class="small">EOBD režimy 03 / 07 · motorová ECU</span></div><div class="notice">Renault DF kódy, ABS, airbag a další jednotky vyžadují odpovídající databázi. Prázdný seznam EOBD neznamená, že celé vozidlo nemá závady.</div><div class="panel">${state.faultRead?state.dtcs.length?`<table><thead><tr><th>KÓD</th><th>POPIS</th><th>STAV</th></tr></thead><tbody>${state.dtcs.map(d=>`<tr><td><strong class="amber">${esc(d.code)}</strong></td><td>${esc(d.description||'Popis není v lokálním katalogu. Ověřte dokumentaci ECU.')}</td><td>${esc(d.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><div class="big">✓</div><h3>Žádné emisní závady ve čtených režimech</h3><p>Ostatní jednotky nebyly prověřeny.</p></div>':'<div class="empty"><div class="big">△</div><h3>Závady zatím nejsou načtené</h3><p>Připojte adaptér a spusťte čtení.</p></div>'}</div>`;}
function ecus(){return workflows.scanView();}
function expert(){return `<div class="toolbar"><button id="importDdt" class="primary">＋ Načíst JSON / ecu.zip</button><input id="ddtFile" type="file" accept=".json,.zip" multiple hidden><input id="ddtSearch" placeholder="Filtrovat definice…" aria-label="Filtrovat definice"></div><div class="form-grid"><div class="field"><label for="ddtSelect">Definice jednotky (${ddtIndex.length})</label><select id="ddtSelect"><option value="">Vyberte definici ECU</option>${ddtIndex.slice(0,1000).map((e,i)=>`<option value="${i}">${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Aktivní jednotka</label><div class="small">${state.ecu?esc(state.ecu.name)+' · '+esc(state.ecu.protocol)+' · TX '+esc(state.ecu.toIdHex)+' / RX '+esc(state.ecu.fromIdHex):'Vyberte definici přesně odpovídající vašemu vozidlu a ECU.'}</div></div></div><div class="notice">V této verzi je implementována komunikace DDT přes CAN ISO-TP. K-line, CLIP a konkrétní scénáře PyRenu nejsou implementovány. Automatický CAN sken najdete v Řídicích jednotkách; servisní runner v Servisních funkcích. Databáze nejsou součástí aplikace.</div>${state.ecu?`<div class="toolbar"><select id="ddtRequest" aria-label="Čtecí požadavek"><option value="">Vyberte čtecí požadavek</option>${state.ecu.reads().map((r,i)=>`<option value="${i}">${esc(r.name)} · ${esc(r.sentbytes)}</option>`).join('')}</select><button id="ddtRead" class="primary" ${!state.connected||state.demo?'disabled':''}>Načíst</button><button id="ddtIdentify" ${!state.connected||state.demo?'disabled':''}>Identifikace VIN (F190)</button></div><div class="panel table-scroll"><table><thead><tr><th>PARAMETR</th><th>HODNOTA</th><th>JEDNOTKA</th></tr></thead><tbody id="ddtRows">${state.ddtResults.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.value)}</td><td>${esc(r.unit)}</td></tr>`).join('')}</tbody></table></div><div class="help panel" style="margin-top:18px"><h2>Zápis konfigurace</h2><p>Řízený zápis jednoho DID (2E) najdete v Pro konzoli. Před zápisem načte původní hodnotu, uloží zálohu a ověří výsledek zpětným čtením. Bitová pole z DDT se zde automaticky nezapisují.</p><button id="gotoConsole">Otevřít konzoli →</button></div>`:'<div class="panel empty"><div class="big">◇</div><h3>Vaše databáze. Vaše jednotky.</h3><p>Definice se zpracují lokálně. Neukládají se na server.<br>Po obnovení stránky je načtěte znovu.</p></div>'}`;}
function service(){return workflows.serviceView();}
function backups(){return `<div class="toolbar"><button id="report" class="primary">↓ Diagnostický report JSON</button><button id="exportBackups">↓ Zálohy konfigurace</button><button id="source">↓ Zdrojový kód a most</button></div><div class="notice">Zálohy jsou pouze v tomto prohlížeči. Exportujte je před vymazáním dat prohlížeče. Obnova kontroluje VIN, adresu ECU i hodnotu předchozího zápisu.</div><div class="panel"><div class="panel-title">ZÁPISY KONFIGURACE <span>${state.backups.length}</span></div>${state.backups.length?`<div class="table-scroll"><table><thead><tr><th>ČAS / ECU</th><th>DID</th><th>PŮVODNÍ → NOVÁ</th><th>VÝSLEDEK</th><th></th></tr></thead><tbody>${state.backups.map((b,i)=>`<tr><td>${esc(b.time)}<br>${esc(b.ecu)}</td><td>${esc(b.did)}</td><td>${esc(b.old)} → ${esc(b.value)}</td><td>${esc(b.status)}</td><td><button data-restore="${i}" ${!state.connected||state.demo?'disabled':''}>Obnovit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="big">↶</div><h3>Zatím žádný zápis</h3><p>Před každým řízeným zápisem se uloží původní hodnota.</p></div>'}</div>`;}
function consoleView(){return `<div class="notice">Surová konzole pro čtení: ELM identifikace a OBD dotazy 01/03/07/09/0A nebo DDT čtení 21/22. Změny konfigurace provádějte formulářem řízeného zápisu níže.</div><div class="toolbar"><select id="consoleType" aria-label="Protokol konzole"><option value="obd">ELM / EOBD</option><option value="ddt">CAN · aktivní DDT ECU</option></select><input id="raw" placeholder="Např. 010C nebo 22F190" aria-label="Diagnostický příkaz"><button id="sendRaw" class="primary" ${!state.connected||state.demo?'disabled':''}>Odeslat →</button><button id="logExport">↓ Log</button></div><pre id="traffic" class="panel code"></pre><section class="panel help"><h2>Řízený zápis DID · UDS 2E</h2><p>Vyžaduje vybranou CAN ECU, známé VIN a přesnou dokumentaci. Původní hodnota se přečte službou 22. Zápis má stejnou délku a následně se ověří. Bez SecurityAccess; zabezpečená ECU jej může odmítnout.</p><div class="form-grid"><div class="field"><label for="writeDid">DID (4 hex znaky)</label><input id="writeDid" placeholder="např. z dokumentace ECU" maxlength="4"></div><div class="field"><label for="writeData">Nová hodnota (hex)</label><input id="writeData" placeholder="Přesný obsah DID"></div></div><button id="prepareWrite" ${!state.connected||state.demo||!state.ecu?'disabled':''}>Načíst původní hodnotu a připravit zápis</button></section>`;}
function settingsView(){return `<div class="panel help"><h2>Vozidlo</h2><div class="form-grid"><div class="field"><label for="profile">Generace</label><select id="profile">${Object.entries(profiles).map(([id,p])=>`<option value="${id}" ${id===settings.profile?'selected':''}>${p.name} · ${p.years}</option>`).join('')}</select></div><div class="field"><label for="year">Rok výroby</label><select id="year">${Array.from({length:22},(_,i)=>2003+i).map(y=>`<option ${y==settings.year?'selected':''}>${y}</option>`).join('')}</select></div></div><p id="profileNote">${profiles[settings.profile].note}</p><h2>Připojení adaptéru</h2>${connectionFields()}<button id="saveSettings" class="primary">Uložit nastavení</button><p class="small">Změna připojení a vozidla je dostupná po odpojení adaptéru.</p></div>`;}
function connectionFields(){return `<div class="field"><label for="transport">Způsob připojení</label><select id="transport"><option value="ble" ${settings.transport==='ble'?'selected':''}>Bluetooth LE · Web Bluetooth</option><option value="serial" ${settings.transport==='serial'?'selected':''}>USB / Bluetooth sériový port · Web Serial</option><option value="bridge" ${settings.transport==='bridge'?'selected':''}>Bluetooth Classic · lokální WebSocket most</option></select></div><div class="form-grid"><div class="field"><label for="baud">Sériová rychlost</label><select id="baud">${[9600,38400,115200,230400].map(b=>`<option ${b==settings.baud?'selected':''}>${b}</option>`).join('')}</select></div><div class="field"><label for="bridge">Lokální most</label><input id="bridge" value="${esc(settings.bridge)}"></div></div><p class="small">BLE API: ${BleTransport.available?'dostupné':'nedostupné v tomto prohlížeči'} · Serial API: ${SerialTransport.available?'dostupné':'nedostupné v tomto prohlížeči'}<br>iPhone: kompatibilní BLE adaptér + Bluefy. macOS/Windows: Chrome nebo Edge. Bluetooth Classic vyžaduje sériový port nebo lokální most.</p>`;}
function about(){return `<div class="panel help"><h2>Diagnostika s jasným rozsahem</h2><p>EspaceWeb 0.2 je experimentální webová aplikace inspirovaná ZoeWeb. Obsahuje skutečné ELM327 připojení, standardní EOBD čtení a DDT CAN čtení / řízený zápis. Není plnou náhradou PyRenu. Komunikace nebyla ověřena na skutečném vozidle.</p><h2>Kompatibilita</h2><div class="table-scroll"><table><thead><tr><th>ZAŘÍZENÍ</th><th>PŘIPOJENÍ</th></tr></thead><tbody><tr><td>iPhone / iPad</td><td>BLE adaptér + Bluefy s Web Bluetooth. Safari/Chrome: pouze rozhraní a demo.</td></tr><tr><td>MacBook</td><td>Chrome/Edge: BLE nebo USB. Párovaný Bluetooth Classic přes dostupný sériový port / most.</td></tr><tr><td>Windows</td><td>Chrome/Edge: BLE nebo USB/COM. Classic přes COM / most.</td></tr></tbody></table></div><p>Úspěch závisí na GATT profilu adaptéru, jeho kvalitě, podpoře protokolů a ECU. Wi-Fi adaptéry se z webu nepřipojují přímo k TCP portu.</p><h2>Co ještě chybí k plnému PyRenu</h2><p>CLIP databázový engine, K-line DDT, Renault DF katalogy, port konkrétních scénářů PyRenu a úplné bitové konfigurace. CAN sken a deklarativní servisní runner jsou dostupné v nabídce Řídicí jednotky a Servisní funkce. Espace VI není ověřený a může vyžadovat autorizovaný přístup k zabezpečené bráně. Výběr ročníku není záruka podpory.</p><h2>Lokální most pro Bluetooth Classic</h2><p>Ze zdrojového balíčku spusťte <code>python -m pip install -r tools/requirements.txt</code> a potom <code>python tools/bridge.py --port COM5</code> (Windows) nebo <code>python3 tools/bridge.py --port /dev/cu.OBDII</code> (macOS). Most i web musí být na stejném počítači. Podrobný návod je v README.</p><h2>Zdrojové kódy a licence</h2><p>GPL-3.0-or-later. Transporty, ISO-TP ovladač, DDT parser a ZIP čtečka vycházejí z <a href="https://github.com/pjpetrov/zoeweb" target="_blank" rel="noopener">ZoeWeb ↗</a>, commit eb8bc28. Původní autoři: pjpetrov a přispěvatelé CanZE. Úpravy a česká aplikace: EspaceWeb. Referenční rozsah: <a href="https://gitlab.com/py_ren/pyren/-/tree/pyren3" target="_blank" rel="noopener">PyRen ↗</a>. Proprietární databáze Renault nejsou přiloženy. Nezávislý projekt bez spojení s Renault.</p><button id="source" class="primary">↓ Stáhnout zdrojový kód a návod</button></div>`;}
function render(){const views={dashboard,live,faults,ecus,expert,service,backups,console:consoleView,settings:settingsView,about};$('#content').innerHTML=views[state.view]();bind();updateValues();if(state.view==='console')renderLog();}
function bind(){workflows.bind();for(const [id,view] of [['gotoFaults','faults'],['gotoLive','live'],['gotoExpert','expert'],['gotoConsole','console']])$('#'+id)?.addEventListener('click',()=>location.hash=view);$('#report')?.addEventListener('click',exportReport);$('#source')?.addEventListener('click',()=>{const a=document.createElement('a');a.href='espaceweb-source.zip';a.download='espaceweb-source.zip';a.click();});$('#exportBackups')?.addEventListener('click',()=>download('espace-backups.json',JSON.stringify(state.backups,null,2)));$('#pidSearch')?.addEventListener('input',e=>document.querySelectorAll('[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(e.target.value.toLowerCase())));$('#record')?.addEventListener('click',()=>{if(!state.connected)return toast('Nejprve připojte vozidlo nebo spusťte demo.');state.recording=!state.recording;render();});$('#csv')?.addEventListener('click',()=>{if(!state.records.length)return toast('Zatím nebyly zaznamenány žádné hodnoty.');const cols=['time','simulated',...PIDS.map(p=>p.key)];download('espace-data.csv','\uFEFF'+cols.join(';')+'\n'+state.records.map(r=>cols.map(k=>r[k]??'').join(';')).join('\n'),'text/csv;charset=utf-8');});$('#readFaults')?.addEventListener('click',()=>job(readFaults));$('#clearFaults')?.addEventListener('click',clearFaults);$('#importDdt')?.addEventListener('click',()=>$('#ddtFile').click());$('#ddtFile')?.addEventListener('change',importDdt);$('#ddtSelect')?.addEventListener('change',e=>selectEcu(e.target.value));$('#ddtSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#ddtSelect').innerHTML='<option value="">Vyberte definici ECU</option>'+ddtIndex.map((d,i)=>d.name.toLowerCase().includes(q)?`<option value="${i}">${esc(d.name)}</option>`:'').join('');});$('#ddtRead')?.addEventListener('click',()=>job(readDdt));$('#ddtIdentify')?.addEventListener('click',()=>job(async()=>{const v=await ecuRead('22F190');const vin=hexAscii(v.slice(6));if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin))throw Error('ECU neposkytla platné VIN.');state.vin=vin;toast('VIN: '+vin);}));$('#ecuSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-ecu]').forEach(r=>r.hidden=!ddtIndex[Number(r.dataset.ecu)].name.toLowerCase().includes(q));});document.querySelectorAll('[data-open-ecu]').forEach(b=>b.onclick=async()=>{await selectEcu(b.dataset.openEcu);location.hash='expert';});$('#sendRaw')?.addEventListener('click',()=>job(sendRaw));$('#raw')?.addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendRaw').click();});$('#logExport')?.addEventListener('click',()=>download('espace-traffic.json',JSON.stringify(state.log,null,2)));$('#prepareWrite')?.addEventListener('click',()=>job(prepareWrite));$('#saveSettings')?.addEventListener('click',()=>{if(state.connected)return toast('Před změnou nastavení odpojte adaptér.');try{readSettings();save();render();toast('Nastavení uloženo.');}catch(e){toast(e.message);}});$('#profile')?.addEventListener('change',e=>$('#profileNote').textContent=profiles[e.target.value].note);document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>job(()=>prepareRestore(Number(b.dataset.restore))));}
async function job(fn){if(state.busy)return toast('Probíhá jiný požadavek.');state.busy=true;try{while(state.polling)await new Promise(r=>setTimeout(r,30));await fn();}catch(e){toast(e.message);log('error',e.message);}finally{state.busy=false;}}
function readSettings(){const p=$('#profile')?.value||settings.profile,y=Number($('#year')?.value||settings.year);const ranges={iv:[2003,2014],v:[2015,2023],vi:[2023,2024]};if(y<ranges[p][0]||y>ranges[p][1])throw Error('Rok výroby neodpovídá zvolené generaci.');settings={...settings,profile:p,year:y,transport:$('#transport').value,baud:Number($('#baud').value),bridge:$('#bridge').value.trim()};}
$('#vehicle').onclick=()=>{location.hash='settings';};$('#connect').onclick=()=>{if(state.busy||workflows.isRunning())return toast('Nejprve zastavte probíhající postup.');if(state.connected)return disconnect();modal('<h2>Připojit vozidlo</h2><p>Zapněte zapalování a připojte ELM327 do diagnostické zásuvky.</p>'+connectionFields()+'<button id="doConnect" class="primary full">Vybrat adaptér a připojit →</button><button id="doDemo" class="full">Prohlédnout demo bez vozidla</button>');$('#doDemo').onclick=()=>{$('#modal').close();startDemo();};$('#doConnect').onclick=()=>{try{readSettings();save();}catch(e){return toast(e.message);}job(connect);};};
async function connect(){if(settings.transport==='ble'&&!BleTransport.available)throw Error('Tento prohlížeč nemá Web Bluetooth. Na iOS použijte Bluefy, na počítači Chrome/Edge.');if(settings.transport==='serial'&&!SerialTransport.available)throw Error('Web Serial není dostupné. Použijte Chrome/Edge na počítači.');if(settings.transport==='bridge'){const u=new URL(settings.bridge);if(!['ws:','wss:'].includes(u.protocol)||!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error('Lokální most musí směřovat na localhost / 127.0.0.1.');}transport=settings.transport==='serial'?new SerialTransport(settings.baud):settings.transport==='bridge'?new WsTransport(settings.bridge):new BleTransport();try{await transport.connect();channel=new CommandChannel(transport,log);await channel.init();protocol='obd';state.connected=true;state.demo=false;state.values={};state.history=[];state.dtcs=[];state.faultRead=false;state.vin=null;state.unsupported.clear();state.paused=false;$('#modal').close();if(transport.device)transport.device.addEventListener('gattserverdisconnected',()=>{if(state.connected)disconnect();});const vinResponse=await channel.command('0902',10000).catch(()=>null);if(vinResponse)state.vin=decodeVin(vinResponse);updateStatus();render();startPolling();toast('Adaptér připojen. Načítám dostupné EOBD parametry.');}catch(e){await transport?.disconnect().catch(()=>{});state.connected=false;updateStatus();throw e;}}
async function disconnect(){if(workflows.isRunning()&&state.connected){toast('Spojení se přerušilo během postupu. Stav ECU ověřte ve vozidle.');}pollGeneration++;clearTimeout(timer);state.connected=false;state.demo=false;state.recording=false;state.paused=false;channel?.cancel();await transport?.disconnect().catch(()=>{});transport=null;channel=null;elm=null;state.values={};state.history=[];state.dtcs=[];state.faultRead=false;state.vin=null;updateStatus();render();}
async function startDemo(){if(state.busy)return;await disconnect();state.connected=true;state.demo=true;state.faultRead=false;state.vin='VF1DEMA0000000001';updateStatus();sampleDemo();render();startPolling();}
function sampleDemo(){const t=Date.now()/6000;state.values={speed:Math.round(64+12*Math.sin(t)),rpm:Math.round(1840+300*Math.sin(t)),coolant:87+Math.sin(t)/2,voltage:14.2,load:34+10*Math.sin(t),fuel:68,intake:31,map:122+12*Math.sin(t),maf:23+5*Math.sin(t),throttle:27+8*Math.sin(t),ambient:14};}
function recordSample(){const item={time:new Date().toISOString(),simulated:state.demo,...state.values};state.history.push(item);if(state.history.length>60)state.history.shift();if(state.recording){state.records.push(item);if(state.records.length>10000){state.recording=false;toast('Dosažen limit 10 000 vzorků. Exportujte CSV.');}}updateValues();}
function startPolling(){const generation=++pollGeneration;let index=0;const poll=async()=>{if(generation!==pollGeneration||!state.connected)return;try{if(!state.busy&&!state.paused){if(state.demo){sampleDemo();recordSample();}else{state.polling=true;try{await ensureObd();const p=PIDS[index++%PIDS.length];if(!state.unsupported.has(p.key)){const v=await channel.pid(p);if(v!=null)state.values[p.key]=v;else state.unsupported.add(p.key);}if(index%PIDS.length===0)recordSample();updateValues();}finally{state.polling=false;}}}}catch(e){log('error',e.message);toast('Chyba čtení: '+e.message);if(/neodpověděl|lost|disconnect/i.test(e.message)){await disconnect();return;}}if(generation===pollGeneration)timer=setTimeout(poll,state.demo?1000:120);};timer=setTimeout(poll,150);}
async function ensureObd(){if(protocol==='obd')return;channel=new CommandChannel(transport,log);await channel.init();protocol='obd';}
async function ensureDdt(){if(!state.ecu)throw Error('Vyberte DDT jednotku.');if(state.ecu.demoOnly)throw Error('Simulovaná ECU nesmí komunikovat se skutečným vozidlem.');if(!state.connected||state.demo)throw Error('Je nutné skutečné připojení.');if(!/CAN/i.test(state.ecu.protocol))throw Error('K-line DDT není v této verzi implementováno.');if(!/^(?:[0-9a-f]{3}|[0-9a-f]{8})$/i.test(state.ecu.toIdHex)||!/^(?:[0-9a-f]{3}|[0-9a-f]{8})$/i.test(state.ecu.fromIdHex))throw Error('Definice neobsahuje platné CAN adresy.');if(protocol!=='ddt'){elm=new Elm327(transport,log);await elm.init();protocol='ddt';}state.paused=true;updateStatus();}
async function ecuRead(hex){await ensureDdt();const r=await elm.requestIsoTp(state.ecu.handle(),hex);const pos=(parseInt(hex.slice(0,2),16)+0x40).toString(16);if(!r.toLowerCase().startsWith(pos+hex.slice(2).toLowerCase()))throw Error('Neočekávaná odpověď ECU: '+r);return r;}
const hexAscii=h=>(h.match(/../g)||[]).map(x=>String.fromCharCode(parseInt(x,16))).join('').replace(/\0/g,'').trim();
async function readFaults(){if(state.demo){state.dtcs=[{code:'P0299',description:'Nedostatečný plnicí tlak turbodmychadla (ukázková závada)',status:'Simulace · uložená'},{code:'P0380',description:'Obvod žhavení (ukázková závada)',status:'Simulace · čekající'}];}else{await ensureObd();const stored=await channel.command('03',15000),pending=await channel.command('07',15000);if(!/43/i.test(stored)||!/47/i.test(pending))throw Error('ECU nepotvrdila oba režimy 03/07. Závady nelze vyhodnotit.');state.dtcs=[...decodeDtcs(stored).map(code=>({code,status:'Uložená'})),...decodeDtcs(pending,'47').map(code=>({code,status:'Čekající'}))];}state.faultRead=true;updateStatus();render();}
function clearFaults(){modal('<h2>Smazat emisní závady?</h2><p>Vymaže uložené emisní kódy a související diagnostické informace včetně freeze-frame a readiness. Nejprve uložte report. Motor má být vypnutý, zapalování zapnuté.</p><label class="field">Pro potvrzení napište SMAZAT<input id="confirmText" autocomplete="off"></label><button id="doClear" class="primary full" disabled>Potvrdit smazání</button>');$('#confirmText').oninput=e=>$('#doClear').disabled=e.target.value!=='SMAZAT';$('#doClear').onclick=()=>job(async()=>{if($('#confirmText').value!=='SMAZAT')return;$('#modal').close();if(state.demo){state.dtcs=[];state.faultRead=true;}else{await ensureObd();const r=await channel.command('04',15000);if(!/(^|[\r\n])44\s*([\r\n>]|$)/i.test(r))throw Error('ECU nepotvrdila smazání: '+r);await readFaults();}updateStatus();render();toast(state.demo?'Simulované závady smazány.':'ECU potvrdila smazání emisních závad.');});}
async function importDdt(e){await job(async()=>{for(const file of e.target.files){if(file.size>80*1024*1024)throw Error('Soubor překračuje 80 MB.');if(/\.zip$/i.test(file.name)){const archive=await file.arrayBuffer();const entries=listZip(archive).filter(x=>/\.json$/i.test(x.name));if(entries.length>30000||entries.some(x=>x.size>10*1024*1024))throw Error('ZIP obsahuje příliš mnoho nebo příliš velké definice.');for(const entry of entries)ddtIndex.push({name:entry.name,get:async()=>parseDdt(await extractText(archive,entry),entry.name)});}else{const text=await file.text();const ecu=parseDdt(text,file.name);ddtFiles.push(ecu);ddtIndex.push({name:ecu.name,get:async()=>ecu});}}ddtIndex.sort((a,b)=>a.name.localeCompare(b.name));render();toast('Načteno '+ddtIndex.length+' definic.');});}
async function selectEcu(index){if(index==='')return;await job(async()=>{state.ecu=await ddtIndex[Number(index)].get();state.ddtResults=[];state.paused=true;render();updateStatus();});}
async function readDdt(){const i=$('#ddtRequest').value;if(i==='')throw Error('Vyberte čtecí požadavek.');const r=state.ecu.reads()[Number(i)],hex=r.sentbytes.replace(/\s/g,'');if(!/^(21|22)([0-9a-f]{2})+$/i.test(hex))throw Error('Neplatný čtecí požadavek.');const response=await ecuRead(hex);state.ddtResults=state.ecu.decode(r,response);render();}
function renderLog(){const el=$('#traffic');if(el){el.textContent=state.log.slice(-150).map(l=>l.time.slice(11,23)+' '+l.dir.toUpperCase().padEnd(5)+' '+l.text.trim()).join('\n')||'Zatím žádná komunikace.';el.scrollTop=el.scrollHeight;}}
async function sendRaw(){let hex=$('#raw').value.replace(/\s/g,'').toUpperCase();if($('#consoleType').value==='ddt'){if(!/^(21|22)([0-9A-F]{2})+$/.test(hex))throw Error('Konzole povoluje pouze čtecí služby 21/22.');await ecuRead(hex);}else{if(!/^(ATI|ATRV|ATDP|ATDPN|01[0-9A-F]{2}|03|07|090[0-9A-F]|0A)$/.test(hex))throw Error('Povolené jsou pouze identifikační a čtecí EOBD příkazy.');await ensureObd();await channel.command(hex,15000);}}
function persistBackups(){localStorage.setItem('espace.backups',JSON.stringify(state.backups));}
async function prepareWrite(){const did=$('#writeDid').value.trim().toUpperCase(),value=$('#writeData').value.replace(/\s/g,'').toUpperCase();if(!/^[0-9A-F]{4}$/.test(did)||!/^(?:[0-9A-F]{2}){1,4}$/.test(value))throw Error('Zadejte platné DID a sudý počet hex znaků (nejvýše 4 bajty; delší ISO-TP zápis není ověřen).');if(!state.vin)throw Error('Nejprve načtěte platné VIN vozidla.');const old=(await ecuRead('22'+did)).slice(6).toUpperCase();if(old.length!==value.length)throw Error('Nová hodnota má jinou délku než původní DID.');if(old===value)throw Error('Hodnota je již nastavena.');confirmWrite({time:new Date().toISOString(),vin:state.vin,ecu:state.ecu.name,tx:state.ecu.toIdHex,rx:state.ecu.fromIdHex,did,old,value,status:'Připraveno'});}
function confirmWrite(b){modal(`<h2>Potvrdit zápis konfigurace</h2><p>${esc(b.ecu)} · VIN ${esc(b.vin)}<br>DID ${b.did}: <code>${b.old}</code> → <code>${b.value}</code></p><p>Vozidlo musí stát a mít stabilní napájení. Ověřte význam DID v dokumentaci přesné ECU.</p><div class="field"><label>Napište ZAPSAT pro potvrzení</label><input id="writeConfirm" autocomplete="off"></div><button id="commitWrite" class="primary full" disabled>Zálohovat a zapsat</button>`);$('#writeConfirm').oninput=e=>$('#commitWrite').disabled=e.target.value!=='ZAPSAT';$('#commitWrite').onclick=()=>job(async()=>{if($('#writeConfirm').value!=='ZAPSAT')return;if(!state.connected||state.demo||state.vin!==b.vin||state.ecu?.toIdHex!==b.tx||state.ecu?.fromIdHex!==b.rx)throw Error('Změnilo se vozidlo nebo ECU. Připravte zápis znovu.');$('#modal').close();const fresh=(await ecuRead('22'+b.did)).slice(6).toUpperCase();if(fresh!==b.old)throw Error('Hodnota se mezitím změnila. Zápis zrušen.');b.status='Pokus o zápis';state.backups.push(b);persistBackups();try{const response=await elm.requestIsoTp(state.ecu.handle(),'2e'+b.did+b.value);if(response.toUpperCase()!=='6E'+b.did)throw Error('ECU nepotvrdila zápis: '+response);const verify=(await ecuRead('22'+b.did)).slice(6).toUpperCase();b.status=verify===b.value?'Ověřeno':'Neshoda při ověření';persistBackups();if(verify!==b.value)throw Error('Zpětné čtení se neshoduje. Původní hodnota je v zálohách.');toast('Zápis ověřen zpětným čtením.');}catch(e){b.status='Chyba / nejistý stav: '+e.message;persistBackups();throw e;}finally{render();}});}
async function prepareRestore(i){const b=state.backups[i];if(!state.ecu||state.vin!==b.vin||state.ecu.toIdHex!==b.tx||state.ecu.fromIdHex!==b.rx)throw Error('Vyberte stejnou ECU a načtěte stejné VIN jako v záloze.');const fresh=(await ecuRead('22'+b.did)).slice(6).toUpperCase();if(fresh!==b.value)throw Error('Aktuální hodnota neodpovídá předchozímu zápisu. Automatická obnova zastavena.');confirmWrite({...b,time:new Date().toISOString(),old:fresh,value:b.old,status:'Připraveno k obnově'});}
profileLabel();updateStatus();navigate();
